def on_wall(sprite, location):
    if current_level == 2 and have_key and tiles.tile_at_location_equals(location, sprites.dungeon.door_closed_north):
        tiles.set_wall_at(location, False)
        tiles.set_tile_at(location, sprites.dungeon.floor_light0)
scene.on_hit_wall(SpriteKind.player, on_wall)

global current_level
if current_level == 1:
    current_level = 2
    load_level()
else:
    game.over(True)
